arguments.content:
hl.config({
    autogenerated = false,
    general = {
        gaps_in = 8,
        gaps_out = 16,
        border_size = 2,
        col = {
            active_border = {
                colors = {"rgba(33ccffee)", "rgba(00ff99ee)"},
                angle = 45
            }
        },
        layout = "dwindle",
        disable_hyprland_logo = false,
        v2_1 = true
    },
    decoration = {
        rounding = 10,
        blur = {
            enabled = true,
            size = 3,
            passes = 1
        }
    },
    animations = {
        enabled = true,
        bezier = "easeOutQuint",
        leaf = "windows",
        speed = 4.79
    },
    input = {
        kb_layout = "fr",
        follow_mouse = 1
    }
})

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

hl.env("XCURSOR_SIZE", "24")

hl.on("hyprland.start", function() hl.exec_cmd("waybar") end)

hl.bind("SUPER + Return", hl.dsp.exec_cmd("kitty"))
hl.bind("SUPER + D", hl.dsp.exec_cmd("rofi -show drun"))
hl.window_rule({ name = "float-pavu", match = { class = "^(pavucontrol)$" }, float = true })

